/**
 * The External API, as MCP tools.
 *
 * **The catalogue is not written here.** `docs/openapi/external-tools.json` is
 * generated by `yarn openapi && yarn tools` from the controller itself, and it
 * already carries every tool's name, description and input schema. Listing
 * them again in code would be a second copy of the same facts, drifting from
 * the first the moment anybody adds an endpoint — which is exactly the reason
 * `scripts/mcp-keycloak-token.ts` refused to wrap these calls at all.
 *
 * What *is* written here is the one thing the JSON cannot express: which
 * method of `ExternalService` each tool reaches, and how a flat bag of
 * arguments becomes that method's parameters. {@link assertCatalogueMatches}
 * keeps the two halves honest.
 */
import { Injectable, Logger, OnModuleInit } from '@nestjs/common';
import { existsSync, readFileSync } from 'node:fs';
import { dirname, join } from 'node:path';
import type { Principal } from '@request-management/share';
import { AppError } from '@request-management/share';
import { ExternalService } from '../external/external.service';

/** One entry of `external-tools.json`. */
interface ToolSpec {
  name: string;
  description: string;
  input_schema: Record<string, unknown>;
  'x-request': { method: string; path: string };
}

/** What MCP's `tools/list` returns per tool. */
export interface McpTool {
  name: string;
  description: string;
  inputSchema: Record<string, unknown>;
}

/** Everything a tool needs beyond its own arguments. */
export interface ToolContext {
  /** The human the work is done as — see `mcp-actor.ts`. */
  readonly actor: Principal;
  /** Forwarded to user-service by the calls that resolve an approval chain. */
  readonly authorization: string;
}

type ToolArgs = Record<string, unknown>;
type ToolHandler = (args: ToolArgs, context: ToolContext) => Promise<unknown>;

/** The catalogue's path inside the repository. */
const CATALOGUE_RELATIVE = join('docs', 'openapi', 'external-tools.json');

/**
 * Finds the generated catalogue, whatever the process was started from.
 *
 * Not `__dirname`: the services build to `dist/` through webpack (AGENTS.md,
 * "Build traps"), so a path relative to the bundle points at nothing. Not
 * `process.cwd()` alone either — that was the first attempt and it failed at
 * boot, because `nest start --watch` runs from `services/core-service` while
 * `yarn openapi` writes to the repo root. Walking up covers both, and every
 * other way this repo is started.
 *
 * `MCP_TOOLS_PATH` overrides it for a deployment that puts the file elsewhere.
 */
function findCatalogue(): { path: string | null; tried: string[] } {
  const override = process.env.MCP_TOOLS_PATH;
  if (override) return { path: override, tried: [override] };

  const tried: string[] = [];
  let directory = process.cwd();

  // Four levels is `services/core-service` to the repo root, twice over.
  for (let depth = 0; depth < 5; depth++) {
    const candidate = join(directory, CATALOGUE_RELATIVE);
    tried.push(candidate);

    if (existsSync(candidate)) return { path: candidate, tried };

    const parent = dirname(directory);
    if (parent === directory) break;
    directory = parent;
  }

  return { path: null, tried };
}

/**
 * Splits the flat argument bag a model sends into the shapes the service
 * expects.
 *
 * A tool's arguments arrive as one object because that is what a JSON schema
 * describes — `generate-tools.ts` flattens path, query and body together on
 * purpose ("a model asked to fill in `Authorization` is a model inventing a
 * token"). The service, being a REST service underneath, wants them separated
 * again.
 */
function rest(args: ToolArgs, ...taken: string[]): ToolArgs {
  const left: ToolArgs = { ...args };
  for (const key of taken) delete left[key];

  return left;
}

function requireString(args: ToolArgs, field: string): string {
  const value = args[field];

  if (typeof value !== 'string' || !value.trim()) {
    throw new AppError('VALIDATION_FAILED', `ต้องระบุ ${field}`, [
      { field, reason: 'required' },
    ]);
  }

  return value;
}

@Injectable()
export class McpToolRegistry implements OnModuleInit {
  private readonly logger = new Logger(McpToolRegistry.name);
  private tools: McpTool[] = [];
  /** Why MCP has no tools, when that is a fault rather than a catalogue. */
  private unavailable: string | null = null;

  constructor(private readonly external: ExternalService) {}

  /**
   * Every tool name mapped to the call behind it.
   *
   * `as never` on the query objects: the DTOs are validated by `ValidationPipe`
   * on the REST path, and nothing validates them here — the schema the model
   * filled in came from those same DTOs, so the shape is right, but TypeScript
   * cannot know that from an untyped bag.
   */
  private readonly handlers: Record<string, ToolHandler> = {
    get_request_types: (args, { actor }) =>
      this.external.listTypes(actor, args),

    get_request_types_code_form: (args, { actor }) =>
      this.external.formOf(requireString(args, 'code'), actor),

    get_requests: (args, { actor }) => this.external.list(actor, args as never),

    get_requests_summary: (args, { actor }) =>
      this.external.summary(actor, args),

    get_requests_ref: (args, { actor }) =>
      this.external.findByRef(requireString(args, 'ref'), actor),

    get_requests_ref_actions: (args, { actor }) =>
      this.external.actionsFor(requireString(args, 'ref'), actor),

    get_requests_ref_tree: (args, { actor }) =>
      this.external.treeOf(requireString(args, 'ref'), actor),

    get_users: (args, { actor }) =>
      this.external.searchUsers(actor, args as never),

    post_requests: (args, { actor, authorization }) =>
      this.external.createAndSubmit(args as never, actor, authorization),

    post_requests_ref_actions_action: (args, { actor, authorization }) =>
      this.external.perform(
        requireString(args, 'ref'),
        requireString(args, 'action'),
        rest(args, 'ref', 'action'),
        actor,
        authorization,
      ),
  };

  /**
   * Loads the catalogue and refuses to start if it disagrees with the table.
   *
   * Failing at boot rather than at call time is the whole point: a tool
   * advertised by `tools/list` and missing from `handlers` would be offered to
   * a model, chosen, and only then found to be unimplemented — reported to the
   * user as the model's mistake.
   */
  onModuleInit(): void {
    const { path, tried } = findCatalogue();

    /*
      A missing catalogue disables MCP. It does **not** take the service down.

      This threw once, and the container would not boot: requests, approvals
      and CRM all offline because one optional endpoint could not find a JSON
      file the image had never been given a copy of. `rm-core is unhealthy`,
      and nothing about the message said which feature was at fault. The blast
      radius has to match the fault.

      Loud, though — the log names the file and the command that regenerates
      it, and every MCP call answers with the same sentence, so a disabled
      feature cannot be mistaken for one that simply has nothing to offer.
    */
    if (!path) {
      this.unavailable =
        `ไม่พบ ${CATALOGUE_RELATIVE} — รัน \`yarn openapi && yarn tools\` ` +
        'แล้ว build ใหม่ (หรือกำหนด MCP_TOOLS_PATH)';

      this.logger.error(
        `MCP ปิดใช้งาน: ${this.unavailable}\n` +
          `  looked in:\n${tried.map((entry) => `    ${entry}`).join('\n')}`,
      );
      return;
    }

    const specs = JSON.parse(readFileSync(path, 'utf8')) as ToolSpec[];

    /*
      A catalogue that *is* present but disagrees with the dispatch table is a
      different kind of fault — a programming error, not a packaging one, and
      one that would offer a model a tool nothing implements. That still
      refuses to start.
    */
    this.assertCatalogueMatches(specs);

    this.tools = specs.map((spec) => ({
      name: spec.name,
      description: spec.description,
      inputSchema: spec.input_schema,
    }));

    this.logger.log(`MCP: ${this.tools.length} tools`);
  }

  private assertCatalogueMatches(specs: ToolSpec[]): void {
    const advertised = new Set(specs.map((spec) => spec.name));
    const implemented = new Set(Object.keys(this.handlers));

    const missing = [...advertised].filter((name) => !implemented.has(name));
    const extra = [...implemented].filter((name) => !advertised.has(name));

    if (missing.length || extra.length) {
      throw new Error(
        'external-tools.json and the MCP dispatch table disagree.\n' +
          (missing.length
            ? `  advertised but not implemented: ${missing.join(', ')}\n`
            : '') +
          (extra.length
            ? `  implemented but not advertised: ${extra.join(', ')}\n`
            : '') +
          '  Run `yarn openapi && yarn tools`, then add the missing handler.',
      );
    }
  }

  list(): McpTool[] {
    return this.tools;
  }

  /** The reason MCP cannot serve, so callers are told rather than left to guess. */
  reasonUnavailable(): string | null {
    return this.unavailable;
  }

  has(name: string): boolean {
    return name in this.handlers;
  }

  call(name: string, args: ToolArgs, context: ToolContext): Promise<unknown> {
    return this.handlers[name](args, context);
  }
}
